P.transport["npc:alanndarian-nightsong"] = {
  hash = "e1fb77",
  fullHash = "b1395a",
  text = "Alanndarian Nightsong. Alanndarian Nightsong is a night elf resident of Auberdine in Darkshore dedicated to tending to the region's beleaguered fauna. She works alongside travelers to remedy the blights plaguing the local wildlife, particularly the native striders and forest creatures corrupted by dark forces. Situated in the coastal settlement of Auberdine, Alanndarian Nightsong watches over the fragile ecological balance of Darkshore. As mysterious taints seep into the soil and waters, the creatures of the ancient woods have begun to succumb to sickness and unnatural aggression. Alanndarian acts as a guardian and naturalist, seeking practical remedies to ease their suffering and restore their natural vigor. Much of Alanndarian's attention is focused on identifying the root causes of the afflictions spreading through the local fauna. Through careful gathering of botanical reagents and researching the principal water sources of the region, she crafts salves and curative draughts. She enlists wandering adventurers to apply these cures directly to ailing forest creatures, attempting to stave off the spreading corruption before it permanently overtakes Darkshore's wildlife.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_alanndarian-nightsong-c78eea84db6ab4723743/1-0000.mp3", duration = 68.3885714, start = 0},
  },
}
P.transport["npc:althea-ebonlocke"] = {
  hash = "9ae60d",
  fullHash = "83a8ad",
  text = "Althea Ebonlocke. Commander Althea Ebonlocke leads the Night Watch, the beleaguered town guard protecting Darkshire from the terrors of Duskwood. A relative of Mayor Ello Ebonlocke, she shoulders the defense of an isolated region abandoned by Stormwind's regular military. She organizes patrols, tasks adventurers with culling local horrors, and coordinates the town's survival against constant monstrous threats. While her relative, Mayor Ello Ebonlocke, handles civil governance within the town hall, Commander Althea directs Darkshire's thin line of physical defense. When Stormwind failed to deploy royal troops to guard Duskwood against creeping horrors, the citizenry formed the Night Watch. Under Althea's steady, unyielding command, these volunteers patrol the fog-shrouded roads, keeping skeletal undead, ferocious wolves, and spiders from overrunning the town perimeter. Althea is pragmatic and understands the limits of her militia. Outnumbered and continually bleeding recruits, she freely enlists passing mercenaries and travelers to thin the threats at Darkshire's doorstep. She directs campaigns against the ghouls and skeletons at the tranquil and sorrowful graveyards of the forest, while remaining vigilant against darker rumors stirring deep in the woods.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_althea-ebonlocke-085de982e8a3f0dd4f9c/1-0000.mp3", duration = 76.2253061, start = 0},
  },
}
P.transport["npc:asterion"] = {
  hash = "145b72",
  fullHash = "af4025",
  text = "Asterion. Asterion is an ancient Highborne spirit bound to the ruins of Bashal'Aran in Darkshore. Once the trusted second to governor Athrikus Narassin ten millennia ago, he was mysteriously imprisoned in a magical moonstone seal that held him through mortal life and into the afterlife. Today, his specter remains shackled to the ruined shrine, surrounded by demonic beasts and dreaming of liberation. Before the Great Sundering shattered ancient Kalimdor, Bashal'Aran and Ameth'Aran were sister cities blessed by Queen Azshara herself. Azshara appointed Athrikus Narassin to govern the twin settlements, and Asterion served as his right hand. Respected for both his physical combat prowess and his command of arcane sorcery, Asterion lived among the people of Bashal'Aran while frequently traveling between the sister cities to manage the needs of their citizens. For reasons lost to time, Asterion fell out of favor with his master. Athrikus fashioned a powerful moonstone seal, forging an inescapable magical cage to confine Asterion within Bashal'Aran. The imprisonment stretched through centuries of agonizing confinement; worse still, when Asterion finally perished, he discovered death offered no release. His spirit remained bound to the ruined shrine, left behind when the world cracked open and demons overran the ancient settlement.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_asterion-87fc5046aa77a0a2d6bf/1-0000.mp3", duration = 80.7183673, start = 0},
  },
}
P.transport["npc:athridas-bearmantle"] = {
  hash = "b2434d",
  fullHash = "a9a383",
  text = "Athridas Bearmantle. Athridas Bearmantle is a night elf druid residing in Dolanaar within the boughs of Teldrassil. Tasked with safeguarding the local settlement, he directs young adventurers to investigate the encroaching corruption affecting the local wildlife and the nearby Gnarlpine furbolgs. Stationed within Dolanaar, Athridas Bearmantle stands as an early line of defense for the night elves emerging from Shadowglen. As the boughs of the newly grown world tree Teldrassil exhibit unnatural signs of decay and unrest, Athridas works tirelessly to coordinate local scouting efforts and protect the peaceful township from surrounding threats. Much of Athridas's concern centers on the neighboring Gnarlpine tribe of furbolgs. Once peaceful neighbors, the Gnarlpine have succumbed to a spreading madness and corruption that poisons their shamans and chieftains, driving them into violent frenzy against the Kaldorei. Athridas mobilizes willing champions to contain the threat and unearth the deeper taint taking root in the wilderness.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_athridas-bearmantle-d744cf17864c23c695a2/1-0000.mp3", duration = 60.16, start = 0},
  },
}
P.transport["npc:blind-mary"] = {
  hash = "29016c",
  fullHash = "789e4f",
  text = "Blind Mary. Blind Mary is a tormented banshee haunting an abandoned, ruined farmhouse just southeast of Darkshire in Duskwood. Once a vain and beautiful mortal woman, her violent death and transformation drove her to self-inflicted mutilation in grief over what she had become. Before the shadows fell across Duskwood, Mary was known as a striking mortal woman who took immense pride in her beauty, rarely seen without her treasured looking glass. When the undead swept over the region, Mary was slain along with many of her neighbors. Unlike those who found rest in the earth, her spirit lingered on as an ethereal banshee, condemned to wander the mortal realm in a ghastly, translucent form. Awakening to undeath, Mary was overwhelmed by sorrow, horror, and fury at her monstrous reflection. Incapable of enduring the sight of her spectral visage, she clawed out her own eyes with her bare hands so she would never gaze upon herself again. In her agony, she discarded her beloved looking glass, leaving her to drift through her abandoned home as a blind, weeping wraith clutching to faint memories of the mortal life she lost.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_blind-mary-12cf07ea50dbe2c91687/1-0000.mp3", duration = 67.7355102, start = 0},
  },
}
P.transport["npc:calor"] = {
  hash = "db2b71",
  fullHash = "c2b10f",
  text = "Calor. Calor is a dedicated resident of Darkshire who aids the Night Watch and the Carevin family in defending Duskwood. Operating under the direction of Jonathan Carevin, he actively coordinates efforts to hunt down the vicious worgen stalking the gloomy forests. Adventurers looking to push back the ravenous beasts haunting the woods often find their assignments through him. Stationed within the beleaguered settlement of Darkshire, Calor works closely with Jonathan Carevin, one of the town's prominent defenders. Amid the endless gloom and creeping terrors of Duskwood, Calor devotes himself to supporting the Carevin household's mission: eradicating the supernatural horrors encroaching upon the town's perimeter before the remaining townsfolk are slaughtered. Calor's primary duty centers on confronting the feral worgen prowling the woods, particularly around blighted areas like the Rotting Orchard. These ferocious wolf-men are far more aggressive and dangerous than common beasts, slaughtering travelers and patrols alike. Calor enlists capable fighters to cull their ranks and investigate their origins, desperate to stem the bloodthirsty tide.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_calor-78c3c685807bf80866f4/1-0000.mp3", duration = 66.7167347, start = 0},
  },
}
P.transport["npc:captain-grayson"] = {
  hash = "becc07",
  fullHash = "195406",
  text = "Captain Grayson. Captain Grayson is the restless spirit of a pirate captain stationed at the Westfall Lighthouse. Having lost his own life when his ship smashed against the dark coastline, he now watches over the beacon to prevent other sailors from suffering his fate. In life, Grayson captained a vessel along the perilous southern seas of the Eastern Kingdoms. His voyage came to a violent end off the jagged shoals of Westfall on a night when the lighthouse fire had gone dark. Cast upon the rocks, Grayson perished alongside his ship, only to awaken as an earthbound phantom trapped upon the coast. Drawn to the Westfall Lighthouse in death, Grayson hoped to find answers about the afterlife. Instead, he witnessed sheer tragedy. A notorious murloc known as Old Murk-Eye drove the lighthouse keeper and his family away. Though the keepers bravely returned to rekindle the flame, Old Murk-Eye rallied the surrounding murlocs for a second, brutal slaughter. Grayson could only watch helplessly as the family was butchered. With the keepers dead and Westfall crumbling under neglect, Captain Grayson took the solemn burden of the beacon upon his spectral shoulders. He seeks aid from passing adventurers to gather fuel for the great flame and avenge the slaughtered family by hunting down Old Murk-Eye and driving back the coastal murloc tide.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_captain-grayson-d81d52c160dc9e4b079d/1-0000.mp3", duration = 78.9681633, start = 0},
  },
}
P.transport["npc:captain-stoutfist"] = {
  hash = "41d02e",
  fullHash = "6e313c",
  text = "Captain Stoutfist. Captain Stoutfist is the dwarven officer in charge of military defenses at Menethil Harbor in the Wetlands. With the Dragonmaw clan pushing aggressively out of their marshland strongholds, Stoutfist coordinates defensive maneuvers and counter-offensives to ensure the vital Alliance port does not fall. Menethil Harbor serves as the principal deepwater port connecting Ironforge and Stormwind to the marshy lowlands of the Wetlands and the sea beyond. As the town's commanding officer, Captain Stoutfist bears the heavy burden of keeping its docks, civilian populace, and garrison secure against surrounding threats. The marshlands are notoriously hazardous, but the biggest peril to the settlement is an organized surge from renegade orcs. The Dragonmaw clan, entrenched within the Wetlands since the Second War, has begun pushing their operations directly toward the roadways and passes. By infiltrating Dun Algaz, they threaten to sever the overland lifeline connecting Loch Modan and Ironforge to Menethil Harbor. Facing a severe shortage of troops, Captain Stoutfist relies on visiting Alliance volunteers recommended by Mountaineer Valstag Ironjaw to stem the tide.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_captain-stoutfist-d3ec8bc7cc615e8c5bb9/1-0000.mp3", duration = 72.0718367, start = 0},
  },
}
P.transport["npc:clerk-daltry"] = {
  hash = "9c0766",
  fullHash = "765ff0",
  text = "Clerk Daltry. Clerk Daltry is the civic record keeper stationed in Darkshire Town Hall in Duskwood. Surrounded by ledgers and registry books, he helps investigate the village's past and track down historical records, even if his archives are somewhat neglected and out of date. While Darkshire struggles against encroaching beasts, undead horrors, and supernatural gloom, everyday civic duties fall to Clerk Daltry. Working out of the Darkshire Town Hall alongside Lord Ello Ebonlocke and the local council, Daltry maintains the town's historical ledgers, property rolls, and census data. In a region fractured by disaster, his records are among the few surviving links to the days before Grand Hamlet fell into shadow. Because Darkshire has been cut off from regular Stormwind administration, Daltry's record-keeping is notoriously imperfect. Old documents go missing, ledgers fall behind, and vital town files are frequently misplaced or damaged. Adventurers investigating local cold cases or long-lost residents frequently consult him, only to find that uncovering the truth requires digging through overlooked notes or venturing out into the dangerous woods to recover lost papers.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_clerk-daltry-ba0b8b28ec1952af3853/1-0000.mp3", duration = 72.96, start = 0},
  },
}
P.transport["npc:collin-mauren"] = {
  hash = "c0384b",
  fullHash = "0793aa",
  text = "Collin Mauren. Collin Mauren is a human mage residing in the Mage Quarter of Stormwind City. A scholarly researcher and crafter of incantations, he experiments with exotic natural reagents to devise unique utility spells. Among his pursuits is assisting his acquaintance, the gnome engineer and explorer Gaxim Rustfizzle, with specialized arcane scrolls. Situated within Stormwind's bustling Mage Quarter, Collin Mauren spends his days pursuing the quieter, more practical applications of magic. Rather than chasing raw elemental power, he focuses on crafting arcane formulas that solve specific, logistical problems. Collin often turns to natural anomalies and raw components scavenged across Azeroth, weaving their intrinsic properties into functional magic scrolls and reagents for friends and travelers alike. Collin maintains a close correspondence and friendship with the gnomish tinker Gaxim Rustfizzle. When Gaxim needed a reliable way to communicate across great distances during his travels, Collin designed a specialized messaging spell. To anchor the spell, he utilizes the whirling debris left behind by Westfall's erratic Dust Devils, capturing the essence of shifting wind to ensure long-distance messages reach his adventurous colleague. Beyond his work with local elementals, Collin's research extends clear across the Great Sea to the crags of Kalimdor. Curiously captivated by the resilient hides of basilisks native to the Stonetalon Mountains, Collin seeks out their scales to synthesize new spells. Travelers venturing into Kalimdor frequently receive his requests for these rare hides, fueling Collin's ongoing fascination with how primal creature anatomy can stabilize complex enchantments.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_collin-mauren-77f171e4fb1733b55102/1-0000.mp3", duration = 105.247347, start = 0},
  },
}
P.transport["npc:corithras-moonrage"] = {
  hash = "5ccf39",
  fullHash = "acaf12",
  text = "Corithras Moonrage. Corithras Moonrage is a night elf scholar and quest giver stationed in the village of Dolanaar on Teldrassil. He guides newly arrived adventurers in understanding the nature of the great World Tree and tasks them with maintaining its sacred moonwells. Through his lessons, he reveals both the spiritual importance of Teldrassil and the growing burdens carried by the kaldorei. Residing in the shaded settlement of Dolanaar, Corithras Moonrage serves as an instructor to travelers leaving the sheltered bounds of Shadowglen. As young kaldorei venture into the wider boughs of Teldrassil, Corithras ensures they understand the history of their new home. He teaches that survival in this changing era requires vigilance and reverence for the natural order. Much of Corithras's duty revolves around collecting moonwell water for the druids in Darnassus. He directs adventurers to collect pure waters from moonwells across Teldrassil in specially crafted phials for delivery to Fandral Staghelm. Through these trials, he monitors the health of the World Tree and seeks to maintain the delicate balance of the wilderness against creeping corruption.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_corithras-moonrage-28a3b0c498b14216c7ad/1-0000.mp3", duration = 67.7616327, start = 0},
  },
}
P.transport["npc:daphne-stilwell"] = {
  hash = "673add",
  fullHash = "6bbeff",
  text = "Daphne Stilwell. Daphne Stilwell tends an isolated orchard nestled atop the coastal cliffs of Westfall overlooking the Longshore. Together with her husband Jordan, she fled turmoil in the north and relocated south, quietly aiding the Church of the Holy Light while defending her home from nearby outlaws. Perched on the bluffs to the west of Moonbrook and the exit of the Deadmines, Daphne Stilwell manages a secluded homestead and apple orchard. From below along the Longshore or above on gryphon routes south to Stranglethorn Vale, the small farm looks quiet and unassuming. Yet running a homestead in modern Westfall is anything but safe. Despite the encroaching bandits and roaming scavengers, Daphne diligently works her trees and keeps watch over her isolated patch of land. Before settling in the hills of Westfall, Daphne and her husband Jordan lived in Lordaeron near Pyrewood Village, working in what is now Shadowfang Keep. When darkness and disaster overtook the region, they were driven southward along with thousands of other human refugees. In Stormwind's orbit, Jordan's renowned craftsmanship and Daphne's steady presence led them to forge close ties with the Church of the Holy Light, providing support and holy arms to paladins of the Silver Hand.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_daphne-stilwell-da9288f8114d371d486d/1-0000.mp3", duration = 75.8334694, start = 0},
  },
}
P.transport["npc:delgren-the-purifier"] = {
  hash = "a4139c",
  fullHash = "a77b13",
  text = "Delgren the Purifier. Delgren the Purifier is a human paladin stationed at Maestra's Post on the northern edge of Ashenvale. Operating alongside comrades Balthule Shadowstrike and Feero Ironhand, he aids the night elves in cleansing demonic and shadow magic threatening the frontier, with a particular focus on the sinister Cult of the Dark Strand. Human paladins are a rare sight deep within the ancient forests of Kalimdor, but Delgren the Purifier arrived with a mission. Affiliated with the Argent Dawn, Delgren traveled west with a cadre of holy warriors determined to assist the Alliance's new night elf allies against the lingering evils of demons and undead remnants from the Third War. Stationed near the border of Darkshore and Ashenvale, he maintains a watchful vigil over travelers passing south from Auberdine. Despite his fierce devotion to the Holy Light and zealous nickname, Delgren possesses an unusual perspective on Kalimdor's tangled politics. Much to the annoyance and disdain of his conservative superiors, he took the time to learn Orcish. This rare linguistic skill hints at an unconventional mind—one that seeks to understand the enemies and neighbors sharing this untamed continent rather than relying solely on blind dogma.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_delgren-the-purifier-f60227ef85485f8c0339/1-0000.mp3", duration = 75.2065306, start = 0},
  },
}
P.transport["npc:denalan"] = {
  hash = "f98110",
  fullHash = "933673",
  text = "Denalan. Denalan is an accomplished night elf herbalist and botanist who tends a quiet lakeside plot along the eastern shore of Lake Al'Ameth. Working under a simple awning, he devotes his days to studying the island's plant life and seeking botanical remedies for the strange corruption affecting Teldrassil. He frequently enlists young adventurers to gather samples, study violent timberlings, and test enchanted soils. While many kaldorei focus on martial vigilance or high druidic rites, Denalan pursues the patient, meticulous craft of herbalism. Stationed along the tranquil eastern banks of Lake Al'Ameth, he has established a modest research camp consisting of a cloth awning, simple field tools, and tidy rows of cultivated planter boxes. Rather than retreating to the grand barrows of Darnassus, he prefers to remain close to the loam, directly examining the unusual flora that has sprouted since the planting of the new World Tree. Denalan's research is far more than an academic curiosity; it addresses the growing unrest among Teldrassil's native wildlife. The timberlings, normally docile woodland beings of wood and sprout, have turned increasingly aggressive. Denalan enchants specialized soil to nurse wild seeds in captivity and analyze how malignant forces seep into the root systems. By studying strange specimens like shimmering fronds, glowing fruit, and moss-twined growths, he seeks to isolate whatever dark taint is troubling the forest boughs.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_denalan-b6fdbb0d3e6396c2881a/1-0000.mp3", duration = 89.9657143, start = 0},
  },
}
